#[no_mangle]
pub unsafe extern "C" fn prefix_function(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<1||n>4097{return -1}let a=std::slice::from_raw_parts(v,n);if a[0]<0||a[0]>4096||n!=a[0] as usize+1{return -1}let len=a[0] as usize;let text=&a[1..];if text.iter().any(|&x|!(0..=127).contains(&x)){return -1}let bytes=4*len;if bytes>cap||(bytes>0&&out.is_null()){return -2}let mut pi=vec![0u32;len];for i in 1..len{let mut j=pi[i-1] as usize;while j>0&&text[i]!=text[j]{j=pi[j-1] as usize}if text[i]==text[j]{j+=1}pi[i]=j as u32}for(i,&x)in pi.iter().enumerate(){let b=x.to_le_bytes();for k in 0..4{*out.add(4*i+k)=b[k]}}bytes as i64}
